        private static void Register(string ns, string name, int typeDef, int methods, Func<VisualElement, gar> factory)
        {
            var desc = new BindingDescriptor
            {
                Namespace = ns,
                ClassName = name,
                TypeDefIndex = typeDef,
                MethodCount = methods,
                Factory = factory
            };
            _descriptors[name] = desc;
            _descriptors[$"{ns}.{name}"] = desc;
        }

        public static bool TryGetDescriptor(string name, out BindingDescriptor desc) => _descriptors.TryGetValue(name, out desc);
        public static gar Create(string name, VisualElement root)
        {
            if (!_initialized) Initialize();
            return _descriptors.TryGetValue(name, out var d) ? d.Factory(root) : new GenericUIBinding(name, 0, root);
        }
